// Builds bench/test/fixtures/recorded (AIR-220 check 2): 3 cases times the 5 default configurations times 2 runs, 30 runs, written once with
// the scripted model into AIR-140's recording format (`writeRecording` and `chatBody`, every call with route `scripted`, so the recordings
// are stand-ins and carry no chat id). The directory is self-contained: llm/, transcripts/, cases/ with the texts they read, results.json
// and MANIFEST.sha256. Run it with `pnpm -C bench exec tsx test/helpers/make-recorded-fixture.ts`; the checked-in output is not regenerated by a test.
import { createHash } from 'node:crypto';
import { cpSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';
import { chatBody, scriptedLlm, setLlmOverride, writeRecording } from '@airlock/runtime/llm';
import { defaultDeps, main } from '../../src/cli.ts';
import { loadCases } from '../../src/runner/cases.ts';
import { asciiJson } from '../../src/runner/record.ts';
import type { ResultsFile } from '../../src/runner/record.ts';
import { FIXTURE_CASES, FIXTURE_ROOT } from './cases.ts';
import { scriptedModel } from './scripted-model.ts';

const MODEL = 'z-ai/glm-5.3-flash';
const EPOCH = '1970-01-01T00:00:00.000Z';
export const RECORDED = join(FIXTURE_ROOT, 'fixtures', 'recorded');

function files(dir: string): string[] {
  return readdirSync(dir, { recursive: true, withFileTypes: true })
    .filter((e) => e.isFile())
    .map((e) => relative(dir, join(e.parentPath, e.name)));
}

export async function build(target: string = RECORDED): Promise<void> {
  const work = mkdtempSync(join(tmpdir(), 'air220-fixture-'));
  try {
    const cases = loadCases(FIXTURE_CASES);
    const llmDir = join(work, 'runs', 'live-fixture', 'llm');
    const s = scriptedLlm(scriptedModel(cases).handler);
    setLlmOverride(async (o) => {
      const r = await s.complete(o);
      await writeRecording(llmDir, o, chatBody({ text: r.text, model: o.model, usage: r.usage }), { route: 'scripted', latencyMs: 0, recordedAt: EPOCH, sourceModel: o.model });
      return r;
    });
    const lines: string[] = [];
    const code = await main(['run', '--model', MODEL, '--n', '2', '--cases', FIXTURE_CASES, '--budget-usd', '5', '--concurrency', '1', '--name', 'fixture'], {
      out: (l) => lines.push(l),
      initCwd: work,
      paths: { results: join(work, 'results'), runs: join(work, 'runs'), doc: join(work, 'BENCH.md') },
      deps: defaultDeps(),
      now: () => new Date(EPOCH),
    });
    if (code !== 0) throw new Error(`the run failed: ${lines.join(' | ')}`);

    rmSync(target, { recursive: true, force: true });
    mkdirSync(target, { recursive: true });
    cpSync(join(work, 'runs', 'live-fixture', 'llm'), join(target, 'llm'), { recursive: true });
    cpSync(join(work, 'runs', 'live-fixture', 'transcripts'), join(target, 'transcripts'), { recursive: true });
    // the cases the runs were made on, with the texts they read (a text ref resolves under the parent of cases/)
    cpSync(FIXTURE_CASES, join(target, 'cases'), { recursive: true });
    cpSync(join(FIXTURE_ROOT, 'fixtures', 'base'), join(target, 'fixtures', 'base'), { recursive: true });
    cpSync(join(FIXTURE_ROOT, 'fixtures', 'payloads'), join(target, 'fixtures', 'payloads'), { recursive: true });
    const results = JSON.parse(readFileSync(join(work, 'results', 'fixture.json'), 'utf8')) as ResultsFile;
    results.meta.bench_commit = 'fixture';
    results.meta.verdict_cli_sha256 = 'fixture';
    writeFileSync(join(target, 'results.json'), asciiJson(results, 1) + '\n', 'utf8');
    const listed = [...files(join(target, 'llm')).map((f) => join('llm', f)), ...files(join(target, 'transcripts')).map((f) => join('transcripts', f))].sort();
    const manifest = listed.map((f) => `${createHash('sha256').update(readFileSync(join(target, f))).digest('hex')}  ${f}`);
    writeFileSync(join(target, 'MANIFEST.sha256'), manifest.join('\n') + '\n', 'utf8');
  } finally {
    setLlmOverride(null);
    rmSync(work, { recursive: true, force: true });
  }
}

const entry = process.argv[1];
if (entry !== undefined && entry === fileURLToPath(import.meta.url)) {
  await build();
  console.log(`wrote ${RECORDED}`);
}
